"use strict";
const assert=require("node:assert/strict"),fs=require("node:fs"),os=require("node:os"),path=require("node:path");
const root=path.resolve(__dirname,"../pilot/nephi-home-node-pilot-v1");
const {migratePostgres}=require(path.join(root,"lib/providers/postgres-migrate"));
const {seedNephiPostgres}=require(path.join(root,"tests/helpers/nephi-postgres-seed"));
const {createPostgresProviders}=require(path.join(root,"lib/providers/postgres-providers"));
const {createApp}=require(path.join(root,"server"));
const checks=[];function check(name,value){assert.ok(value,name);checks.push(name)}
(async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),"nephi-bundle-")),connection={kind:"pglite",dataDir:dir};await migratePostgres(connection);await seedNephiPostgres(connection);const providers=createPostgresProviders(connection);const settings=providers.customerSettings,availability=providers.availability;
try{let bundles=settings.listBundles("nephi_home");check("seed 四房包棟",bundles.length===1&&bundles[0].memberRoomIds.join(",")==="room301,room302,room401,room402");const bundleId=bundles[0].id;
for(const date of ["2026-07-20","2026-07-21"])for(const room of ["room301","room302","room401","room402"])availability.setDay("nephi_home",date,room,"available");availability.setDay("nephi_home","2026-07-20",bundleId,"closed");let row=availability.getRows("nephi_home","2026-07-20","2026-07-21")[0];check("關包棟同步關成員",[bundleId,"room301","room302","room401","room402"].every(id=>row[id]==="closed"));
availability.setDay("nephi_home","2026-07-20",bundleId,"available");row=availability.getRows("nephi_home","2026-07-20","2026-07-21")[0];check("開包棟同步開成員",[bundleId,"room301","room302","room401","room402"].every(id=>row[id]==="available"));availability.setDay("nephi_home","2026-07-20","room301","closed");row=availability.getRows("nephi_home","2026-07-20","2026-07-21")[0];check("關成員使包棟不可售",row[bundleId]==="closed");check("不誤關其他散房",["room302","room401","room402"].every(id=>row[id]==="available"));
availability.setDay("nephi_home","2026-07-20",bundleId,"available");let property=settings.getProperty("nephi_home"),bundleRoom=property.rooms.find(x=>x.id===bundleId);check("方案進入 LINE 房型來源",bundleRoom&&bundleRoom.memberRoomIds.length===4);const app=createApp({providers,structuredClassifier:null,adminAuthRequired:true});let search=app.service.searchAvailability({customerId:"nephi_home",checkIn:"2026-07-20",checkOut:"2026-07-22",guests:6,roomType:"包棟"});check("多晚全部可售才顯示",search.rooms.some(x=>x.id===bundleId));availability.setDay("nephi_home","2026-07-21","room302","closed");search=app.service.searchAvailability({customerId:"nephi_home",checkIn:"2026-07-20",checkOut:"2026-07-22",guests:6,roomType:"包棟"});check("多晚任一天關閉即不顯示",!search.rooms.some(x=>x.id===bundleId));
const other=settings.createBundle("nephi_home",{name:"兩房包棟",memberRoomIds:["room301","room302"],capacity:4,basePrice:5000,enabled:true});check("可建立任意組合",other.memberRoomIds.length===2);settings.updateBundle("nephi_home",other.id,{name:"A 棟包棟",memberRoomIds:["room301","room302"],capacity:4,basePrice:5500,enabled:false});check("可修改方案",settings.listBundles("nephi_home").find(x=>x.id===other.id).name==="A 棟包棟");check("可刪除未使用方案",settings.deleteBundle("nephi_home",other.id)===true);
check("不同 propertyId 不洩漏方案",settings.listBundles("other_home").length===0);const running=await app.start(0,"127.0.0.1");const unauth=await fetch(`${running.url}/api/bundles?customerId=nephi_home`);check("未登入不可讀 API",unauth.status===401);const unauthWrite=await fetch(`${running.url}/api/bundles`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({customerId:"nephi_home",name:"不應建立",memberRoomIds:["room301"],capacity:2,basePrice:1})});check("未登入不可寫 API",unauthWrite.status===401);await app.stop();
}finally{if(providers.close)await providers.close();fs.rmSync(dir,{recursive:true,force:true});}console.log(`${checks.length}/${checks.length} PASS`);})().catch(e=>{console.error(e.stack||e);process.exit(1)});
